import path from 'path';
import fs from 'fs';

import PsyanimFirebaseAdminClient from "../src/integrations/PsyanimFirebaseAdminClient.js";

let serviceAccountFilePath = path.resolve("../keys/psyanim2-backend-ba21021c04b9.json");
let serviceAccount = JSON.parse(fs.readFileSync(serviceAccountFilePath, 'utf8'));

let client = new PsyanimFirebaseAdminClient(serviceAccount);

// client.getAllExperimentMetadataAsync((docs) => {

//     console.log("docs.length = " + docs.length);

//     docs.forEach(doc => {

//         console.log(doc.data());
//     })
// });

client.db
    .collection('trial-metadata')
    .where('data.trialNumber', '>=', 3)
    .get()
    .then((querySnapshot) => {

        let experimentMetadata = [];

        console.log("doc count = " + querySnapshot.docs.length);

        querySnapshot.forEach((doc) => {

            let docData = doc.data();

            experimentMetadata.push(docData);
        });

        console.log(experimentMetadata);
    });
